input.command:
python3 - <<'EOF'
import pandas as pd
for f in ["renewals_2025_export.csv","renewals_due_export.csv"]:
    d=pd.read_csv(f,dtype=str,keep_default_na=False)
    print("=====",f,d.shape)
    for c in ["Prov","Industry","Plan Type","Funding","Channel","Billing","Online Admin?","Wellness Program?","Renewal Status","Account Reviews (12m)","Late Pmts (12m)","Service Issues (12m)"]:
        if c in d: print(c, d[c].value_counts().to_dict())
    print("dup ids",d["Plan ID"].duplicated().sum(),"full dup rows",d.duplicated().sum())
    dd=d[d["Plan ID"].duplicated(keep=False)].sort_values("Plan ID"); print(dd.head(6).to_string())
    for c in ["Renewal Date","Plan Effective Date","Annual Premium","Renewal Increase","Loss Ratio (12m)","Lives Covered","Member App Use %"]:
        print(c, d[c].sample(15,random_state=1).tolist())
    blank=d[(d=="").sum(axis=1)>5]; print("mostly blank rows",len(blank)); print(blank.head().to_string())
EOF

